def verify(result):
    cand = result.get('correct', '') if isinstance(result, dict) else str(result)
    det_val = result['vars']['det_val']
    return det_val < 0 and ('silla' in cand) and ('nodo' not in cand) and ('foco' not in cand) and ('centro' not in cand)

def verify(result):
    a = result['vars']['a']
    b = result['vars']['b']
    c = result['vars']['c']
    d = result['vars']['d']
    return int(result['correct']) == (a*d - b*c)

def verify(result):
    v = result['vars']
    return v['det_val'] > 0 and v['tr_val'] < 0 and any(opt['is_correct'] for opt in result['options'])

def verify(result):
    cand = result.get('correct', '') if isinstance(result, dict) else str(result)
    w2 = result['vars']['w2']
    return w2 > 0 and ('Centro' in cand or 'centro' in cand) and ('Nodo' not in cand) and ('Foco' not in cand) and ('silla' not in cand)
